-- BE-INCR-LEGAL-PARAMS PR-3 (nó LEGAL-PARAMS; BRIEF §3 item 9, D-3; emenda §9 L-1; F-LP-8 b, F-LP-10 b).
-- O Anexo III da IN RFB 1.700/2017 vira tabela de PLATAFORMA (DEPRECIACAO_ANEXO_III); `depreciation_rates` fica só com
-- as linhas CUSTOM de cada escopo. Ordem obrigatória do item 9:
--   (1) coluna nova `fixed_assets.legalParameterId` (L-1, "Coluna nova no bem");
--   (2) semente v3 = cópia byte a byte do fixture anexo-iii-in-1700-2017.json (= prisma/data/legal_parameters_v3.sql);
--   (3) cada bem que aponta para uma linha ANEXO_* por escopo passa a apontar para a linha de plataforma de mesma
--       (source, sourceRow) — as 2 Notas, sem sourceRow, pela chave NOTA — e `rateId` vira NULL. `annualRateBp` (o
--       snapshot gravado no bem) não é tocado;
--   (4) só então as linhas ANEXO_* por escopo saem, por delete físico (F-LP-10 b). Uma linha ANEXO_* ainda referenciada
--       (sem equivalente na plataforma) NÃO sai: o FK Restrict a protege e o teste-guarda acusa.
-- Formato da linha (dono 07/10, questionário): chave = sourceRow (ou NOTA), discriminador = source, tudo no valorJson.
-- vigenteDesde 2017-01-01, sem fim (dono 07/10). Fonte NÃO reconferida (grau C, BRIEF §6 item 1).

-- RedefineTables
PRAGMA defer_foreign_keys=ON;
PRAGMA foreign_keys=OFF;
CREATE TABLE "new_fixed_assets" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" TEXT NOT NULL,
    "unitId" TEXT NOT NULL,
    "classId" TEXT NOT NULL,
    "code" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "ncmPrefix" TEXT,
    "quantity" INTEGER NOT NULL DEFAULT 1,
    "costCents" BIGINT NOT NULL,
    "residualValueCents" BIGINT NOT NULL DEFAULT 0,
    "rateId" TEXT,
    "legalParameterId" TEXT,
    "annualRateBp" INTEGER NOT NULL,
    "bookAnnualRateBp" INTEGER,
    "bookRateJustification" TEXT,
    "openingAccumulatedCents" BIGINT NOT NULL DEFAULT 0,
    "accumulatedDepreciationCents" BIGINT NOT NULL DEFAULT 0,
    "status" TEXT NOT NULL DEFAULT 'PENDING_ACTIVATION',
    "acquiredAt" DATETIME NOT NULL,
    "activatedAt" DATETIME,
    "disposedAt" DATETIME,
    "disposalEntryId" TEXT,
    "sourceDocumentId" TEXT,
    "payableId" TEXT,
    "sourceItemRef" TEXT,
    "version" INTEGER NOT NULL DEFAULT 1,
    "createdById" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    "deletedAt" DATETIME,
    CONSTRAINT "fixed_assets_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "fixed_assets_classId_fkey" FOREIGN KEY ("classId") REFERENCES "fixed_asset_classes" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT "fixed_assets_rateId_fkey" FOREIGN KEY ("rateId") REFERENCES "depreciation_rates" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT "fixed_assets_legalParameterId_fkey" FOREIGN KEY ("legalParameterId") REFERENCES "legal_parameters" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT "fixed_assets_disposalEntryId_fkey" FOREIGN KEY ("disposalEntryId") REFERENCES "journal_entries" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT "fixed_assets_sourceDocumentId_fkey" FOREIGN KEY ("sourceDocumentId") REFERENCES "source_documents" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT "fixed_assets_payableId_fkey" FOREIGN KEY ("payableId") REFERENCES "payables" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
INSERT INTO "new_fixed_assets" ("accumulatedDepreciationCents", "acquiredAt", "activatedAt", "annualRateBp", "bookAnnualRateBp", "bookRateJustification", "classId", "code", "costCents", "createdAt", "createdById", "deletedAt", "description", "disposalEntryId", "disposedAt", "id", "ncmPrefix", "openingAccumulatedCents", "payableId", "quantity", "rateId", "residualValueCents", "sourceDocumentId", "sourceItemRef", "status", "unitId", "updatedAt", "userId", "version") SELECT "accumulatedDepreciationCents", "acquiredAt", "activatedAt", "annualRateBp", "bookAnnualRateBp", "bookRateJustification", "classId", "code", "costCents", "createdAt", "createdById", "deletedAt", "description", "disposalEntryId", "disposedAt", "id", "ncmPrefix", "openingAccumulatedCents", "payableId", "quantity", "rateId", "residualValueCents", "sourceDocumentId", "sourceItemRef", "status", "unitId", "updatedAt", "userId", "version" FROM "fixed_assets";
DROP TABLE "fixed_assets";
ALTER TABLE "new_fixed_assets" RENAME TO "fixed_assets";
CREATE UNIQUE INDEX "fixed_assets_disposalEntryId_key" ON "fixed_assets"("disposalEntryId");
CREATE INDEX "fixed_assets_userId_unitId_status_idx" ON "fixed_assets"("userId", "unitId", "status");
CREATE UNIQUE INDEX "fixed_assets_userId_unitId_code_key" ON "fixed_assets"("userId", "unitId", "code");
CREATE UNIQUE INDEX "fixed_assets_payableId_sourceItemRef_key" ON "fixed_assets"("payableId", "sourceItemRef");
PRAGMA foreign_keys=ON;
PRAGMA defer_foreign_keys=OFF;


