-- Repoint (3): mesma (source, sourceRow). O SET lê o rateId ANTIGO nas duas colunas (SQLite avalia o SET sobre a linha
-- original), então legalParameterId é resolvido antes de rateId virar NULL.
UPDATE "fixed_assets"
SET "legalParameterId" = (
      SELECT lp."id" FROM "depreciation_rates" dr
      JOIN "legal_parameters" lp
        ON lp."tabela" = 'DEPRECIACAO_ANEXO_III' AND lp."status" = 'PUBLISHED'
       AND lp."discriminador" = dr."source"
       AND lp."chave" = COALESCE(CAST(dr."sourceRow" AS TEXT), 'NOTA')
      WHERE dr."id" = "fixed_assets"."rateId"),
    "rateId" = NULL
WHERE "rateId" IN (
      SELECT dr."id" FROM "depreciation_rates" dr
      JOIN "legal_parameters" lp
        ON lp."tabela" = 'DEPRECIACAO_ANEXO_III' AND lp."status" = 'PUBLISHED'
       AND lp."discriminador" = dr."source"
       AND lp."chave" = COALESCE(CAST(dr."sourceRow" AS TEXT), 'NOTA')
      WHERE dr."source" <> 'CUSTOM');

-- Delete físico (4), só do que nenhum bem referencia mais.
DELETE FROM "depreciation_rates"
WHERE "source" <> 'CUSTOM'
  AND "id" NOT IN (SELECT "rateId" FROM "fixed_assets" WHERE "rateId" IS NOT NULL);
